// Generated by running the actual MAX-API pre3 InitDB/InitLogDB at
// 48260ce6517a9ab68851a7ac499477981d78da63, not by migrating current models.
// The fixture contains schema only. All data below is synthetic.
//
//go:embed testdata/sqlite/pre3_schema.sql
var sqlitePre3Schema string

const sqlitePre3SchemaSHA = "f4af2569217ecb14863d551aae40b36d655e821a57503c9cdee5bef34e2a8a26"
const sqliteUpgradeConfigEnv = "MAXAPI_SQLITE_UPGRADE_TEST_CONFIG"

type sqliteUpgradeConfig struct {
	Directory string
	Mode      string
	Recover   bool
}

type sqliteUpgradeCase struct {
	ID            int
	Source, State string
	Quota         int64
}

func (item sqliteUpgradeCase) requestID() string   { return fmt.Sprintf("synthetic-pre3-%d", item.ID) }
func (item sqliteUpgradeCase) tokenID() int        { return item.ID + 1000 }
func (item sqliteUpgradeCase) subscriptionID() int { return item.ID + 2000 }
func (item sqliteUpgradeCase) operationKey() string {
	return BillingRequestFinalizeOperationKey(item.requestID())
}

func sqliteUpgradeCases(mode string) []sqliteUpgradeCase {
	var cases []sqliteUpgradeCase
	for _, source := range []string{BillingSettlementSourceWallet, BillingSettlementSourceSubscription} {
		for _, quota := range []int64{0, 6, 100, 130} {
			states := []string{"pending", "effect_pending", "effect_logged", "complete"}
			if mode == "separate_fresh" {
				// A fresh target requires quiesced effects on the original file.
				// This does not claim an online transfer of pending receipts.
				states = []string{"complete"}
			}
			for _, state := range states {
				cases = append(cases, sqliteUpgradeCase{ID: 8800 + len(cases), Source: source, State: state, Quota: quota})
			}
		}
		if mode != "separate_fresh" {
			for _, state := range []string{"manual", "outcome_unknown"} {
				cases = append(cases, sqliteUpgradeCase{ID: 8800 + len(cases), Source: source, State: state, Quota: 130})
			}
			if source == BillingSettlementSourceSubscription {
				cases = append(cases, sqliteUpgradeCase{ID: 8800 + len(cases), Source: source, State: "period_changed", Quota: 6})
			}
		}
	}
	return cases
}

func openSQLiteUpgradeFixture(t *testing.T, path string, logOnly bool) *gorm.DB {
	return openSQLiteUpgradeSchema(t, path, logOnly, sqlitePre3Schema)
}

func openSQLiteUpgradeSchema(t *testing.T, path string, logOnly bool, schema string) *gorm.DB {
	t.Helper()
	// Git checkouts can convert text fixtures to CRLF on Windows.
	schema = strings.ReplaceAll(schema, "\r\n", "\n")
	require.Equal(t, sqlitePre3SchemaSHA, fmt.Sprintf("%x", sha256.Sum256([]byte(schema))), "historical fixture cannot silently become a current-model schema")
	db, err := gorm.Open(sqlite.Open(path), &gorm.Config{Logger: logger.Default.LogMode(logger.Silent)})
	require.NoError(t, err)
	require.NoError(t, db.Transaction(func(tx *gorm.DB) error {
		for _, statement := range strings.Split(schema, "\n-- MAX_API_SQLITE_SCHEMA_STATEMENT\n")[1:] {
			if logOnly && !strings.Contains(statement, "CREATE TABLE `logs`") &&
				!strings.Contains(statement, "CREATE TABLE `billing_log_receipts`") &&
				!strings.Contains(statement, " ON `logs`") && !strings.Contains(statement, " ON `billing_log_receipts`") {
				continue
			}
			if err := tx.Exec(statement).Error; err != nil {
				return err
			}
		}
		return nil
	}))
	return db
}

func TestSQLitePre3FixtureFormat(t *testing.T) {
	for _, format := range []string{"LF", "CRLF"} {
		t.Run(format, func(t *testing.T) {
			schema := strings.ReplaceAll(sqlitePre3Schema, "\r\n", "\n")
			if format == "CRLF" {
				schema = strings.ReplaceAll(schema, "\n", "\r\n")
			}
			db := openSQLiteUpgradeSchema(t, filepath.Join(t.TempDir(), "fixture.sqlite"), false, schema)
			defer func() { require.NoError(t, closeDB(db)) }()
			var tables, indexes int64
			require.NoError(t, db.Raw("SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'").Scan(&tables).Error)
			require.NoError(t, db.Raw("SELECT COUNT(*) FROM sqlite_master WHERE type = 'index' AND name NOT LIKE 'sqlite_%'").Scan(&indexes).Error)
			require.EqualValues(t, 39, tables)
			require.EqualValues(t, 160, indexes)
		})
	}
}

func seedSQLiteUpgradeFixture(t *testing.T, mode string) string {
	t.Helper()
	directory := filepath.Join(t.TempDir(), "upgrade 中文 space")
	require.NoError(t, os.MkdirAll(directory, 0755))
	db := openSQLiteUpgradeFixture(t, filepath.Join(directory, "ledger.sqlite"), false)
	t.Cleanup(func() { _ = closeDB(db) })
	logDB := db
	if mode == "separate_existing" {
		logDB = openSQLiteUpgradeFixture(t, filepath.Join(directory, "logs.sqlite"), true)
		t.Cleanup(func() { _ = closeDB(logDB) })
		require.False(t, logDB.Migrator().HasTable(&User{}))
	}
	// Seed values directly into the captured schema without running current
	// save hooks or creating current tables before the upgrade under test.
	seed := db.Session(&gorm.Session{SkipHooks: true})
	require.NoError(t, seed.Create(&User{Id: 8700, Username: "synthetic-pre3-history", AffCode: "uphist", Email: "Legacy@Example.invalid", Quota: 3000000000,
		UsedQuota: 4000000000, RequestCount: 7, Status: common.UserStatusEnabled}).Error)
	require.NoError(t, seed.Create(&Token{Id: 8701, UserId: 8700, Key: "synthetic-pre3-history", RemainQuota: 5000000000,
		UsedQuota: 4000000000, Status: common.TokenStatusEnabled}).Error)
	require.NoError(t, seed.Create(&Channel{Id: 8702, UsedQuota: 4000000000}).Error)
	history := Log{Id: 8703, UserId: 8700, Type: LogTypeConsume, Quota: 23, PromptTokens: 10, CompletionTokens: 13,
		Content: "synthetic 历史记录", RequestId: "synthetic-pre3-history", Other: `{"retry_log":true}`}
	require.NoError(t, seed.Create(&history).Error)
	require.NoError(t, seed.Create(&BillingLogReceipt{ID: 8704, OperationKey: "synthetic-pre3-history", ClaimToken: "synthetic-history", CreatedAt: 1700000000}).Error)
	if mode == "separate_existing" {
		target := logDB.Session(&gorm.Session{SkipHooks: true})
		require.NoError(t, target.Create(&Log{Id: 8703, UserId: 8700, Type: LogTypeConsume, Quota: 23,
			Content: "synthetic 独立历史日志", RequestId: "synthetic-pre3-target-history", Other: `{"retry_log":true}`}).Error)
		require.NoError(t, target.Create(&BillingLogReceipt{ID: 8704, OperationKey: "synthetic-pre3-target-history",
			ClaimToken: "synthetic-target-history", CreatedAt: 1700000000}).Error)
	}

	for _, item := range sqliteUpgradeCases(mode) {
		finalized := item.State == "effect_pending" || item.State == "effect_logged" || item.State == "complete"
		amount := int64(100)
		if finalized {
			amount = item.Quota
		}
		wallet := int64(1000)
		if item.Source == BillingSettlementSourceWallet {
			wallet -= amount
		}
		used, requests := int64(0), 0
		if item.State == "complete" {
			used, requests = item.Quota, 1
		}
		require.NoError(t, seed.Create(&User{Id: item.ID, Username: item.requestID(), AffCode: fmt.Sprintf("up%d", item.ID), Quota: wallet, UsedQuota: used,
			RequestCount: requests, Status: common.UserStatusEnabled}).Error)
		require.NoError(t, seed.Create(&Token{Id: item.tokenID(), UserId: item.ID, Key: item.requestID(),
			RemainQuota: 1000 - amount, UsedQuota: amount, Status: common.TokenStatusEnabled}).Error)
		require.NoError(t, seed.Create(&Channel{Id: item.ID, UsedQuota: used}).Error)
		if item.Source == BillingSettlementSourceSubscription {
			allow := false
			require.NoError(t, seed.Create(&SubscriptionPlan{Id: item.ID, Title: item.requestID(), Enabled: true,
				TotalAmount: 1000, AllowWalletOverflow: &allow, QuotaResetPeriod: SubscriptionResetNever}).Error)
			period := int64(1700000000)
			if item.State == "period_changed" {
				period++
			}
			require.NoError(t, seed.Create(&UserSubscription{Id: item.subscriptionID(), UserId: item.ID, PlanId: item.ID,
				AmountTotal: 1000, AmountUsed: amount, Status: "active", StartTime: 1700000000,
				EndTime: 9999999999, LastResetTime: period, AllowWalletOverflow: false}).Error)
			require.NoError(t, seed.Create(&SubscriptionPreConsumeRecord{RequestId: item.requestID(), UserId: item.ID,
				TokenId: item.tokenID(), UserSubscriptionId: item.subscriptionID(), SubscriptionLastResetTime: 1700000000,
				ModelName: "synthetic-upgrade-model", PreConsumed: 100, Status: "consumed", CreatedAt: 1700000001, UpdatedAt: 1700000001}).Error)
		}
		require.NoError(t, seed.Create(&BillingPreConsumeSelection{RequestID: item.requestID(), Source: item.Source,
			UserID: item.ID, TokenID: item.tokenID(), ModelName: "synthetic-upgrade-model", RequestedQuota: 100,
			EffectiveQuota: 100, CreatedAt: 1700000001}).Error)
		prompt, completion := int(item.Quota), 0
		if item.Quota > 0 {
			prompt, completion = int(item.Quota)-2, 2
		}
		effect := BillingSettlementEffect{LogType: LogTypeConsume, Content: "synthetic pre3 recovery", ChannelID: item.ID,
			ModelName: "synthetic-upgrade-model", TokenID: item.tokenID(), TokenName: "synthetic-upgrade-token", Group: "default",
			UpdateUsage: true, Quota: item.Quota, QuotaIsActual: true, PromptTokens: prompt, CompletionTokens: completion, RequestID: item.requestID()}
		payload, err := common.Marshal(effect)
		require.NoError(t, err)
		record := BillingSettlement{OperationKey: item.operationKey(), Source: item.Source, UserID: item.ID, TokenID: item.tokenID(),
			FundingDelta: item.Quota - 100, TokenDelta: item.Quota - 100, Status: BillingSettlementStatusPending,
			Revision: 1, EffectPayload: string(payload), EffectStatus: BillingSettlementEffectPending, CreatedAt: 1700000002, UpdatedAt: 1700000002}
		if item.Source == BillingSettlementSourceSubscription {
			record.SubscriptionID, record.SubscriptionPreConsumeRequestID = item.subscriptionID(), item.requestID()
		}
		if finalized {
			record.Status = BillingSettlementStatusApplied
			record.AppliedFundingDelta, record.AppliedTokenDelta = record.FundingDelta, record.TokenDelta
		}
		if item.State == "manual" || item.State == "outcome_unknown" {
			record.Status = item.State
		}
		if item.State == "complete" {
			record.EffectStatus = BillingSettlementEffectApplied
		}
		require.NoError(t, seed.Create(&record).Error)
		if item.State == "effect_logged" || item.State == "complete" {
			logs := logDB.Session(&gorm.Session{SkipHooks: true})
			require.NoError(t, logs.Create(&Log{UserId: item.ID, Type: LogTypeConsume, Quota: int(item.Quota), PromptTokens: prompt,
				CompletionTokens: completion, ModelName: effect.ModelName, TokenId: item.tokenID(), RequestId: item.requestID()}).Error)
			require.NoError(t, logs.Create(&BillingLogReceipt{OperationKey: item.operationKey(), ClaimToken: "synthetic-old-receipt", CreatedAt: 1700000003}).Error)
		}
	}
	require.NoError(t, closeDB(logDB))
	if logDB != db {
		require.NoError(t, closeDB(db))
	}
	require.NoError(t, os.WriteFile(filepath.Join(directory, ".synthetic-upgrade-fixture"), []byte(sqlitePre3SchemaSHA), 0600))
	return directory
}

// A cold process runs the real master startup with isolated globals and
// connections. The parent never substitutes a fresh AutoMigrate schema.
func TestSQLiteUpgradeProcessHelper(t *testing.T) {
	encoded := os.Getenv(sqliteUpgradeConfigEnv)
	if encoded == "" {
		t.Skip("cold-start helper invoked by TestSQLitePre3Upgrade")
	}
	var config sqliteUpgradeConfig
	require.NoError(t, common.UnmarshalJsonStr(encoded, &config))
	marker, err := os.ReadFile(filepath.Join(config.Directory, ".synthetic-upgrade-fixture"))
	require.NoError(t, err)
	require.Equal(t, sqlitePre3SchemaSHA, string(marker))
	require.Contains(t, []string{"shared", "legacy_local", "separate_existing", "separate_fresh"}, config.Mode)
	t.Setenv("SQL_DSN", "local")
	t.Setenv("LOG_SQL_DSN", "")
	t.Setenv("LOG_SQLITE_PATH", "")
	t.Setenv("SQL_MAX_IDLE_CONNS", "1")
	t.Setenv("SQL_MAX_OPEN_CONNS", "1")
	t.Setenv("QUOTA_DATA_AGGREGATE_MIGRATION_ENABLED", "false")
	if config.Mode == "legacy_local" {
		t.Setenv("LOG_SQL_DSN", "local")
	}
	if strings.HasPrefix(config.Mode, "separate_") {
		t.Setenv("LOG_SQLITE_PATH", filepath.Join(config.Directory, "logs.sqlite"))
	}
	common.SQLitePath = filepath.Join(config.Directory, "ledger.sqlite")
	common.IsMasterNode, common.UsingSQLite = true, true
	common.UsingMySQL, common.UsingPostgreSQL = false, false
	common.RedisEnabled, common.BatchUpdateEnabled, common.DataExportEnabled = false, false, false
	common.LogConsumeEnabled, common.DebugEnabled = true, false
	logRetryMarkerBackfillAsyncRunner = func(fn func()) { fn() }
	require.NoError(t, InitDB())
	require.NoError(t, InitLogDB())
	t.Cleanup(func() { require.NoError(t, CloseDB()) })
	DB.Logger, LOG_DB.Logger = logger.Default.LogMode(logger.Silent), logger.Default.LogMode(logger.Silent)
	var history User
	require.NoError(t, DB.First(&history, 8700).Error)
	require.Equal(t, "synthetic-pre3-history", history.Username)
	if config.Recover {
		ProcessPendingBillingSettlementsOnce()
		ProcessPendingBillingSettlementsOnce()
		for _, item := range sqliteUpgradeCases(config.Mode) {
			var record BillingSettlement
			require.NoError(t, DB.Where("operation_key = ?", item.operationKey()).First(&record).Error)
			if item.State == "manual" || item.State == "outcome_unknown" || item.State == "period_changed" {
				continue
			}
			var effect BillingSettlementEffect
			require.NoError(t, common.UnmarshalJsonStr(record.EffectPayload, &effect))
			for range 2 {
				applied, duplicate, err := ApplyBillingSettlementOnce(BillingSettlementInput{OperationKey: record.OperationKey,
					Source: record.Source, UserID: record.UserID, SubscriptionID: record.SubscriptionID, TokenID: record.TokenID,
					FundingDelta: record.FundingDelta, TokenDelta: record.TokenDelta,
					SubscriptionPreConsumeRequestID: record.SubscriptionPreConsumeRequestID, Effect: &effect})
				require.NoError(t, err)
				require.True(t, duplicate)
				require.Equal(t, item.Quota-100, applied)
				require.NoError(t, ProcessBillingSettlementEffect(record.OperationKey))
			}
		}
	}
}

func runSQLiteUpgradeProcess(t *testing.T, config sqliteUpgradeConfig) {
	t.Helper()
	encoded, err := common.Marshal(config)
	require.NoError(t, err)
	ctx, cancel := context.WithTimeout(context.Background(), 45*time.Second)
	defer cancel()
	command := exec.CommandContext(ctx, os.Args[0], "-test.run=^TestSQLiteUpgradeProcessHelper$", "-test.count=1", "-test.timeout=40s", "-test.v")
	for _, entry := range os.Environ() {
		if !strings.HasPrefix(entry, sqliteUpgradeConfigEnv+"=") {
			command.Env = append(command.Env, entry)
		}
	}
	command.Env = append(command.Env, sqliteUpgradeConfigEnv+"="+string(encoded))
	output, err := command.CombinedOutput()
	require.NoError(t, err, "cold startup/recovery: %s", output)
}

func sqliteUpgradeFinancialSnapshot(t *testing.T, directory string) string {
	t.Helper()
	db, err := gorm.Open(sqlite.Open(filepath.Join(directory, "ledger.sqlite")), &gorm.Config{Logger: logger.Default.LogMode(logger.Silent)})
	require.NoError(t, err)
	defer func() { require.NoError(t, closeDB(db)) }()
	var users []struct {
		Id               int
		Quota, UsedQuota int64
		RequestCount     int
	}
	var tokens []Token
	var subscriptions []UserSubscription
	var selections []BillingPreConsumeSelection
	var reservations []SubscriptionPreConsumeRecord
	var settlements []BillingSettlement
	var channels []struct {
		Id        int
		UsedQuota int64
	}
	require.NoError(t, db.Model(&User{}).Order("id").Find(&users).Error)
	require.NoError(t, db.Order("id").Find(&tokens).Error)
	require.NoError(t, db.Order("id").Find(&subscriptions).Error)
	require.NoError(t, db.Order("id").Find(&selections).Error)
	require.NoError(t, db.Order("id").Find(&reservations).Error)
	require.NoError(t, db.Order("id").Find(&settlements).Error)
	require.NoError(t, db.Model(&Channel{}).Order("id").Find(&channels).Error)
	data, err := common.Marshal([]any{users, tokens, subscriptions, selections, reservations, settlements, channels})
	require.NoError(t, err)
	return string(data)
}

func assertSQLiteUpgradedRecovery(t *testing.T, directory, mode string) {
	t.Helper()
	db, err := gorm.Open(sqlite.Open(filepath.Join(directory, "ledger.sqlite")), &gorm.Config{Logger: logger.Default.LogMode(logger.Silent)})
	require.NoError(t, err)
	defer func() { require.NoError(t, closeDB(db)) }()
	logDB := db
	if strings.HasPrefix(mode, "separate_") {
		logDB, err = gorm.Open(sqlite.Open(filepath.Join(directory, "logs.sqlite")), &gorm.Config{Logger: logger.Default.LogMode(logger.Silent)})
		require.NoError(t, err)
		defer func() { require.NoError(t, closeDB(logDB)) }()
		require.False(t, logDB.Migrator().HasTable(&User{}))
		require.False(t, logDB.Migrator().HasTable(&BillingSettlement{}))
	}
	for _, item := range sqliteUpgradeCases(mode) {
		t.Run(fmt.Sprintf("%s/%s/quota%d", item.Source, item.State, item.Quota), func(t *testing.T) {
			blocked := item.State == "manual" || item.State == "outcome_unknown" || item.State == "period_changed"
			amount := item.Quota
			if blocked {
				amount = 100
			}
			var user User
			var token Token
			var channel Channel
			var record BillingSettlement
			require.NoError(t, db.First(&user, item.ID).Error)
			require.NoError(t, db.First(&token, item.tokenID()).Error)
			require.NoError(t, db.First(&channel, item.ID).Error)
			require.NoError(t, db.Where("operation_key = ?", item.operationKey()).First(&record).Error)
			wallet := int64(1000)
			if item.Source == BillingSettlementSourceWallet {
				wallet -= amount
			}
			require.Equal(t, wallet, user.Quota)
			require.Equal(t, 1000-amount, token.RemainQuota)
			require.Equal(t, amount, token.UsedQuota)
			require.Equal(t, item.Source, record.Source)
			require.Equal(t, item.ID, record.UserID)
			require.Equal(t, item.tokenID(), record.TokenID)
			if item.Source == BillingSettlementSourceSubscription {
				var subscription UserSubscription
				require.NoError(t, db.First(&subscription, item.subscriptionID()).Error)
				require.Equal(t, amount, subscription.AmountUsed)
				require.False(t, subscription.AllowWalletOverflow)
				var reservation SubscriptionPreConsumeRecord
				require.NoError(t, db.Where("request_id = ?", item.requestID()).First(&reservation).Error)
				require.EqualValues(t, 1700000000, reservation.SubscriptionLastResetTime)
				require.EqualValues(t, 100, reservation.PreConsumed)
				require.Equal(t, item.subscriptionID(), record.SubscriptionID)
			}
			if blocked {
				want := item.State
				if want == "period_changed" {
					want = BillingSettlementStatusManual
				}
				require.Equal(t, want, record.Status)
				require.Zero(t, record.AppliedFundingDelta)
				require.Zero(t, record.AppliedTokenDelta)
				require.Zero(t, user.UsedQuota)
				require.Zero(t, user.RequestCount)
				require.Zero(t, channel.UsedQuota)
			} else {
				require.Equal(t, BillingSettlementStatusApplied, record.Status)
				require.Equal(t, BillingSettlementEffectApplied, record.EffectStatus)
				require.Equal(t, item.Quota-100, record.AppliedFundingDelta)
				require.Equal(t, item.Quota-100, record.AppliedTokenDelta)
				require.Equal(t, item.Quota, user.UsedQuota)
				require.Equal(t, 1, user.RequestCount)
				require.Equal(t, item.Quota, channel.UsedQuota)
			}
			var logs, receipts int64
			require.NoError(t, logDB.Model(&Log{}).Where("request_id = ?", item.requestID()).Count(&logs).Error)
			require.NoError(t, logDB.Model(&BillingLogReceipt{}).Where("operation_key = ?", item.operationKey()).Count(&receipts).Error)
			want := int64(1)
			if blocked || mode == "separate_fresh" {
				want = 0
			}
			require.Equal(t, want, logs)
			require.Equal(t, want, receipts)
			if want == 1 {
				var log Log
				require.NoError(t, logDB.Where("request_id = ?", item.requestID()).First(&log).Error)
				require.EqualValues(t, item.Quota, log.Quota)
				require.EqualValues(t, item.Quota, log.PromptTokens+log.CompletionTokens)
				if item.State == "effect_logged" || item.State == "complete" {
					var receipt BillingLogReceipt
					require.NoError(t, logDB.Where("operation_key = ?", item.operationKey()).First(&receipt).Error)
					require.Equal(t, "synthetic-old-receipt", receipt.ClaimToken)
					require.EqualValues(t, 1700000003, receipt.CreatedAt)
				}
			}
		})
	}
	var history User
	require.NoError(t, db.First(&history, 8700).Error)
	require.EqualValues(t, 3000000000, history.Quota)
	require.EqualValues(t, 4000000000, history.UsedQuota)
	require.Equal(t, 7, history.RequestCount)
	require.Equal(t, "Legacy@Example.invalid", history.Email)
	require.Equal(t, "legacy@example.invalid", history.NormalizedEmail)
	var historyLog Log
	require.NoError(t, db.First(&historyLog, 8703).Error)
	require.Equal(t, "synthetic 历史记录", historyLog.Content)
	require.Equal(t, 23, historyLog.Quota)
	require.Equal(t, !strings.HasPrefix(mode, "separate_"), historyLog.IsRetry)
	var receipt BillingLogReceipt
	require.NoError(t, db.First(&receipt, 8704).Error)
	require.Equal(t, "synthetic-pre3-history", receipt.OperationKey)
	require.Equal(t, "synthetic-history", receipt.ClaimToken)
	var options []Option
	require.NoError(t, db.Find(&options).Error)
	var completed []Option
	for _, option := range options {
		if strings.HasPrefix(option.Key, logRetryMarkerBackfillOptionKey) {
			completed = append(completed, option)
		}
	}
	require.Len(t, completed, 1, "repeated startup retains one completion identity for the active file")
	require.Equal(t, "true", completed[0].Value)
	if mode == "shared" {
		require.Equal(t, logRetryMarkerBackfillOptionKey, completed[0].Key)
	} else {
		require.NotEqual(t, logRetryMarkerBackfillOptionKey, completed[0].Key)
	}
	if mode == "separate_existing" {
		var targetHistory Log
		require.NoError(t, logDB.First(&targetHistory, 8703).Error)
		require.Equal(t, "synthetic 独立历史日志", targetHistory.Content)
		require.True(t, targetHistory.IsRetry)
		require.True(t, targetHistory.IsErrorRetry)
		require.NoError(t, logDB.First(&receipt, 8704).Error)
		require.Equal(t, "synthetic-pre3-target-history", receipt.OperationKey)
		require.Equal(t, "synthetic-target-history", receipt.ClaimToken)
	}
	if mode == "separate_fresh" {
		var logs, receipts int64
		require.NoError(t, logDB.Model(&Log{}).Count(&logs).Error)
		require.NoError(t, logDB.Model(&BillingLogReceipt{}).Count(&receipts).Error)
		require.Zero(t, logs, "fresh target does not implicitly copy old history")
		require.Zero(t, receipts)
	}
}

func TestSQLitePre3Upgrade(t *testing.T) {
	for _, mode := range []string{"shared", "legacy_local", "separate_existing", "separate_fresh"} {
		t.Run(mode, func(t *testing.T) {
			directory := seedSQLiteUpgradeFixture(t, mode)
			before := sqliteUpgradeFinancialSnapshot(t, directory)
			config := sqliteUpgradeConfig{Directory: directory, Mode: mode}
			for range 2 {
				runSQLiteUpgradeProcess(t, config)
				require.Equal(t, before, sqliteUpgradeFinancialSnapshot(t, directory), "startup migration must not debit/refund or change a durable intent")
			}
			config.Recover = true
			runSQLiteUpgradeProcess(t, config)
			assertSQLiteUpgradedRecovery(t, directory, mode)
			settled := sqliteUpgradeFinancialSnapshot(t, directory)
			runSQLiteUpgradeProcess(t, config)
			assertSQLiteUpgradedRecovery(t, directory, mode)
			require.Equal(t, settled, sqliteUpgradeFinancialSnapshot(t, directory), "fresh-process recovery returns recorded outcomes without another mutation")
		})
	}
}
